export type ShelfLocation = 'canvas/tools' | 'outline/actions';
export interface ShelfAction {
  readonly commandId: string;
  readonly group?: string;
  readonly priority?: number;
  readonly [key: string]: unknown;
}
interface StoredAction { action: ShelfAction; sequence: number; }

export class ActionShelfRegistry {
  private readonly entries = new Map<ShelfLocation, StoredAction[]>();
  private nextSequence = 0;

  constructor(private readonly warn: (message: string) => void = () => undefined) {
    this.entries.set('canvas/tools', []);
    this.entries.set('outline/actions', []);
  }

  private valid(location: string): location is ShelfLocation {
    return location === 'canvas/tools' || location === 'outline/actions';
  }

  register(location: string, action: ShelfAction): void {
    const priority = action.priority ?? 0;
    if (!this.valid(location) || !action.commandId.trim() ||
        !Number.isFinite(priority) || !Number.isInteger(priority)) {
      this.warn('Invalid shelf action');
      return;
    }

    const items = this.entries.get(location)!;
    const index = items.findIndex(item => item.action.commandId === action.commandId);
    const copy: ShelfAction = { ...action, group: action.group ?? '', priority };

    if (index >= 0) {
      items[index] = { action: copy, sequence: items[index].sequence };
    } else {
      items.push({ action: copy, sequence: this.nextSequence++ });
    }
  }

  remove(location: string, commandId: string): void {
    if (!this.valid(location)) {
      this.warn('Invalid shelf location');
      return;
    }
    const items = this.entries.get(location)!;
    const index = items.findIndex(item => item.action.commandId === commandId);
    if (index >= 0) items.splice(index, 1);
  }

  list(location: string): ShelfAction[] {
    if (!this.valid(location)) return [];
    return [...this.entries.get(location)!]
      .sort((a, b) =>
        (a.action.group ?? '').localeCompare(b.action.group ?? '') ||
        (b.action.priority ?? 0) - (a.action.priority ?? 0) ||
        a.sequence - b.sequence)
      .map(item => ({ ...item.action }));
  }
}

