import { ActionShelfRegistry, ShelfAction, ShelfLocation } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

const warnings: string[] = [];
const registry = new ActionShelfRegistry(message => warnings.push(String(message)));
const canvas = 'canvas/tools' as ShelfLocation;
const outline = 'outline/actions' as ShelfLocation;

registry.register(canvas, { commandId: 'late', group: 'beta', priority: 0 } as ShelfAction);
registry.register(canvas, { commandId: 'second', group: 'alpha', priority: 5 } as ShelfAction);
registry.register(canvas, { commandId: 'first', group: 'alpha', priority: 5 } as ShelfAction);
registry.register(canvas, { commandId: 'early', group: 'alpha', priority: -1 } as ShelfAction);
registry.register(canvas, { commandId: 'defaults' } as ShelfAction);
registry.register(outline, { commandId: 'outline-only', group: 'alpha', priority: 0 } as ShelfAction);

let listed = registry.list(canvas) as Array<Record<string, unknown>>;
assert(listed.map(item => item.commandId).join(',') === 'defaults,early,second,first,late', 'actions should sort by group, priority, then registration position');
const defaults = listed.find(item => item.commandId === 'defaults')!;
assert(defaults.group === '' && defaults.priority === 0, 'missing group and priority should receive defaults');
assert((registry.list(outline) as unknown as Array<Record<string, unknown>>).map(item => item.commandId).join(',') === 'outline-only', 'locations should be independent');

registry.register(canvas, { commandId: 'second', group: 'alpha', priority: 5, label: 'replacement' } as unknown as ShelfAction);
listed = registry.list(canvas) as unknown as Array<Record<string, unknown>>;
assert(listed.map(item => item.commandId).join(',') === 'defaults,early,second,first,late', 'replacement should retain the original tie-breaking position');
assert(listed.find(item => item.commandId === 'second')!.label === 'replacement', 'replacement should replace action data');

const one = registry.list(canvas) as unknown as Array<Record<string, unknown>>;
const two = registry.list(canvas) as unknown as Array<Record<string, unknown>>;
assert(one !== two && one[0] !== two[0], 'list should return fresh arrays and action objects');
one[0].commandId = 'damaged';
one.push({ commandId: 'injected' });
assert((registry.list(canvas) as unknown as Array<Record<string, unknown>>)[0].commandId === 'defaults', 'returned values must not expose internal state');

const warningCount = warnings.length;
registry.register('bad/location' as ShelfLocation, { commandId: 'bad' } as ShelfAction);
registry.register(canvas, { commandId: '   ' } as ShelfAction);
registry.register(canvas, { commandId: 'nan', priority: Number.NaN } as ShelfAction);
registry.register(canvas, { commandId: 'infinite', priority: Number.POSITIVE_INFINITY } as ShelfAction);
registry.register(canvas, { commandId: 'fractional', priority: 1.5 } as ShelfAction);
assert(warnings.length === warningCount + 5, 'each invalid registration should warn');
assert((registry.list(canvas) as unknown as Array<Record<string, unknown>>).length === 5, 'invalid registrations should make no change');
assert((registry.list('bad/location' as ShelfLocation) as unknown[]).length === 0, 'invalid locations should list as empty');

const beforeInvalidRemove = warnings.length;
registry.remove('bad/location' as ShelfLocation, 'late');
assert(warnings.length === beforeInvalidRemove + 1, 'invalid removal locations should warn');
registry.remove(outline, 'late');
assert((registry.list(canvas) as unknown[]).length === 5, 'remove should affect only the exact location');
registry.remove(canvas, 'late');
assert(!(registry.list(canvas) as unknown as Array<Record<string, unknown>>).some(item => item.commandId === 'late'), 'exact command should be removed');
registry.remove(canvas, 'missing');
assert((registry.list(canvas) as unknown[]).length === 4, 'removing a missing command should make no change');

